  { id: "magnet-sheet-wall", title: "賃貸でもOK！マグネットシートで磁石がくっつく壁に変身", desc: "賃貸で壁に棚をつけたいけど穴あけは無理…。貼るだけで磁石がくっつく壁に変身するマグネットシートが話題。フックや鍵掛けを自由自在に設置できます。", item_category: "magnet", room_category: "entrance", price_original: "約3,000〜8,000円（壁面収納リフォーム）", price_diy: "約500〜1,000円", time_est: "約15分", hero_image: "https://img.youtube.com/vi/UtVLfQX8miY/maxresdefault.jpg", youtube_id: "UtVLfQX8miY", ingredients: [{ name: "マグネットシート（ホームセンター）", price: "500〜800円" }, { name: "剥がせる両面テープ（賃貸対応）", price: "100〜200円" }, { name: "マグネット付きフック類（ダイソー）", price: "各110円" }], is_100yen_only: false, steps: [{ num: 1, title: "シートをサイズに合わせてカットする", detail: "ハサミでカットできます。使いたい範囲だけでOKです。" }, { num: 2, title: "両面テープで壁に貼り付ける", detail: "賃貸対応の剥がせる両面テープを使えば退去時も安心。シートをしっかり押さえます。" }, { num: 3, title: "マグネットグッズを配置して完成", detail: "マグネットフックや収納グッズを自由に配置すれば完成。玄関・キッチン・デスク周りにも応用できます！" }] },

  // ══ 組み合わせ系DIY ══
  { id: "combo-caster-wire-kitchen", title: "キャスター＋ワイヤーネットで作るキッチンの神ワゴン", desc: "ダイソーのワイヤーネット数枚とキャスターを組み合わせて作るキッチンワゴン。側面にフックやバスケットを好きなだけ追加でき、野菜・調味料・キッチンペーパーをまとめて管理できます。市販品の約1/5の価格で完成！", item_category: "caster", room_category: "kitchen", price_original: "約8,000〜15,000円（市販のキッチンワゴン）", price_diy: "約1,500〜2,000円", time_est: "約40分", hero_image: "https://img.youtube.com/vi/GVMbtYQpQuI/maxresdefault.jpg", youtube_id: "GVMbtYQpQuI", ingredients: [{ name: "ワイヤーネット（大）×4〜6枚", price: "各200円（ダイソー）" }, { name: "ワイヤーバスケット", price: "200〜300円" }, { name: "キャスター×4", price: "100円" }, { name: "結束バンド", price: "100円" }, { name: "S字フック×複数", price: "110円" }], is_100yen_only: true, steps: [{ num: 1, title: "ワイヤーネットで箱型を組む", detail: "前面・背面・側面・底面のネットを結束バンドで固定して箱を作ります。高さはネットのサイズで調整。" }, { num: 2, title: "キャスターを底面に固定する", detail: "底面のネットの格子にキャスターを結束バンドでしっかり固定します。走行方向を揃えると動かしやすくなります。" }, { num: 3, title: "側面にバスケットやフックを追加する", detail: "ワイヤーバスケットをサイドに引っかけます。S字フックでキッチンツールも吊り下げればスペースが最大限活用できます。" }, { num: 4, title: "好みの場所に設置して完成", detail: "コンロ横・冷蔵庫横など使いたい場所へ移動。カスタムは後からいつでも変えられます！" }] },

  { id: "combo-magnet-iron-kitchen", title: "マグネット＋アイアンバーで作るプロ顔負けのキッチン壁面収納", desc: "「冷蔵庫の横が何もない」を変えよう。ダイソーのアイアンバーをマグネットで冷蔵庫側面に取り付け、そこにS字フックでキッチンツールを掛けるだけ。ほぼ5分・300円台で料理し やすいキッチンが完成します！", item_category: "magnet", room_category: "kitchen", price_original: "約3,000〜8,000円（市販の壁面収納ラック）", price_diy: "約330〜550円", time_est: "約5分", hero_image: "https://img.youtube.com/vi/TzuKvpiyycc/maxresdefault.jpg", youtube_id: "TzuKvpiyycc", ingredients: [{ name: "アイアンバー（ダイソー）", price: "110〜220円" }, { name: "強力マグネット×2（ダイソー）", price: "110円" }, { name: "S字フック×複数（ダイソー）", price: "110円" }], is_100yen_only: true, steps: [{ num: 1, title: "アイアンバーに強力マグネットを取り付ける", detail: "アイアンバーの端2箇所に強力マグネットを接着orネジで固定します。" }, { num: 2, title: "冷蔵庫の側面にくっつける", detail: "マグネットで冷蔵庫側面にアイアンバーを固定。磁力で意外としっかり支えられます。" }, { num: 3, title: "S字フックでキッチンツールを掛けて完成", detail: "おたま・ターナー・トング等を掛ければ完成。取り出しやすさが格段に上がり、調理がスムーズになります！" }] },

  { id: "combo-hook-wire-closet", title: "突っ張り棒＋ワイヤーネットで作るクローゼット収納革命", desc: "クローゼットの「上段の棚が届かない」「床に物が散乱する」問題を解決。突っ張り棒とワイヤーネットを組み合わせれば追加棚・バッグ掛け・ベルト収納が全部300円台で実現します！", item_category: "hook", room_category: "storage", price_original: "約4,000〜8,000円（クローゼット用収納グッズセット）", price_diy: "約330〜660円", time_est: "約20分", hero_image: "https://img.youtube.com/vi/JeA6g0mqd7c/maxresdefault.jpg", youtube_id: "JeA6g0mqd7c", ingredients: [{ name: "突っ張り棒（長め）×2本（ダイソー）", price: "各110〜220円" }, { name: "ワイヤーネット（クローゼット幅に合わせて）", price: "200円" }, { name: "S字フック×複数（ダイソー）", price: "110円" }, { name: "結束バンド", price: "100円" }], is_100yen_only: true, steps: [{ num: 1, title: "クローゼット内に突っ張り棒を2本渡す", detail: "上下2本を平行に設置します。幅が広い場合は補強用にもう1本中央に追加するとよいです。" }, { num: 2, title: "ワイヤーネットを突っ張り棒の上に乗せる", detail: "ネットを上の突っ張り棒と下の突っ張り棒に結束バンドで固定して棚を作ります。" }, { num: 3, title: "S字フックでバッグやベルトを吊り下げて完成", detail: "ネットの格子部分にS字フックを引っかければ、バッグ・ベルト・スカーフなどの吊り下げ収納が完成！" }] },

  { id: "combo-wood-iron-desk", title: "板材＋アイアンブラケットで作るおしゃれなデスクサイド棚", desc: "デスクに物が溢れている人に。セリアの板材とアイアンブラケットを組み合わせれば、デスクの横やモニター横に自分だけの小棚が作れます。スマホ・本・コーヒーを置けるシンプルな高見え棚が完成。", item_category: "iron", room_category: "desk", price_original: "約3,000〜6,000円（市販のデスク用サイドシェルフ）", price_diy: "約330〜500円", time_est: "約20分", hero_image: "https://img.youtube.com/vi/BVb3GgUuT0Q/maxresdefault.jpg", youtube_id: "BVb3GgUuT0Q", ingredients: [{ name: "アイアンスクエアブラケット×2（セリア）", price: "220円" }, { name: "ひのき材 or すのこ（棚板用）（セリア）", price: "110〜220円" }, { name: "ネジ or 木工ボンド", price: "100円〜" }], is_100yen_only: true, steps: [{ num: 1, title: "棚板のサイズを決める", detail: "デスクの横に置くなら30cm幅が標準的。セリアのひのき材はちょうどよいサイズが揃っています。" }, { num: 2, title: "ブラケットと棚板を固定する", detail: "ブラケット2個を棚板の裏面にネジで固定します。左右の位置を揃えることがポイントです。" }, { num: 3, title: "デスク横の壁に取り付けて完成", detail: "ブラケットを壁面にネジで固定。賃貸なら剥がせる粘着テープを使った固定もできます。" }] },

  { id: "combo-caster-wood-storage", title: "すのこ＋キャスターで作る「見せる」プランター台", desc: "部屋の隅に鉢植えをただ置いているだけではもったいない。ダイソーのすのことキャスターを組み合わせれば、日当たりに合わせて移動できる「おしゃれなプランタースタンド」が330円で完成します！", item_category: "caster", room_category: "living", price_original: "約2,000〜5,000円（市販のプランタースタンド）", price_diy: "約220〜330円", time_est: "約10分", hero_image: "https://img.youtube.com/vi/T8_2FP65bLQ/maxresdefault.jpg", youtube_id: "T8_2FP65bLQ", ingredients: [{ name: "桐すのこ or 木製まな板（ダイソー）", price: "110〜220円" }, { name: "キャスター（粘着テープ式）×4（ダイソー）", price: "110円" }], is_100yen_only: true, steps: [{ num: 1, title: "すのこの裏面にキャスターを貼る", detail: "粘着テープ式キャスターの保護紙をはがし、すのこ裏面の四隅にしっかり貼り付けます。" }, { num: 2, title: "キャスターが固定されるまで押さえる", detail: "30秒ほど各キャスターを押さえて接着させます。乾燥時間ゼロで即使用できます。" }, { num: 3, title: "植木鉢を乗せて完成", detail: "鉢を乗せれば完成。太陽の動きに合わせて転がして移動すれば、植物がより元気に育ちます！" }] },

  { id: "combo-magnet-wire-fridge", title: "マグネット＋ワイヤーネットで冷蔵庫横をフル活用する収納術", desc: "冷蔵庫の横ってスペースが余ってること多いですよね。マグネットとワイヤーネットを組み合わせることで、ラップ・袋・調味料を冷蔵庫横にスッキリ収納できます。取り外し・移動も自由！", item_category: "magnet", room_category: "kitchen", price_original: "約3,000〜6,000円（スリム収納ラック）", price_diy: "約420〜530円", time_est: "約15分", hero_image: "https://img.youtube.com/vi/0YhVnv6CZJE/maxresdefault.jpg", youtube_id: "0YhVnv6CZJE", ingredients: [{ name: "ワイヤーネット（縦長・ダイソー）", price: "200円" }, { name: "強力マグネット×4（ダイソー）", price: "110円" }, { name: "ワイヤーバスケット×2（ダイソー）", price: "各110円" }, { name: "結束バンド", price: "100円" }], is_100yen_only: true, steps: [{ num: 1, title: "ワイヤーネットに強力マグネットを取り付ける", detail: "ネットの四隅の格子に強力マグネットを結束バンドで固定します。" }, { num: 2, title: "冷蔵庫の側面に貼り付ける", detail: "マグネットで冷蔵庫側面にネットをくっつけます。磁力が強すぎる場合は保護フィルムを挟むと傷が防げます。" }, { num: 3, title: "バスケットを引っかけて完成", detail: "ネットの格子にワイヤーバスケットを引っかけます。ラップ・ホイル・ポリ袋などを入れれば完成！" }] },
  { id: "wood-monitor-stand", title: "ダイソーの板で自作！コスパ最強のPCモニタースタンド", desc: "市販のモニタースタンドを買うと3000円以上。ダイソーのMDF材と木工ボンドを組み合わせるだけで、キーボードが下に収納できる500円の高見えモニタースタンドが完成します！", item_category: "wood", room_category: "desk", price_original: "約3,000円〜", price_diy: "約500円", time_est: "約30分", hero_image: "https://img.youtube.com/vi/KH6lNH9DpU8/maxresdefault.jpg", youtube_id: "KH6lNH9DpU8", is_100yen_only: true, ingredients: [{ name: "MDF材 400x200（天板）", price: "110円（ダイソー）" }, { name: "MDF材 200x100（脚）×2", price: "各110円（ダイソー）" }, { name: "木工ボンド", price: "110円" }], steps: [{ num: 1, title: "脚を固定する", detail: "天板の裏面両端に、木工ボンドで脚となる板を垂直に接着します。" }, { num: 2, title: "重しをのせて乾燥", detail: "上に本などの重しを乗せて数時間放置。驚くほどガッチリ固まります。" }, { num: 3, title: "デスクに設置", detail: "モニターを乗せ、下にキーボードを収納すればデスクが広々使えます。" }] },
  { id: "paint-iron-rust", title: "100均塗料で魔法の手法！プラスチックが「錆びた鉄」に変わるアイアンペイント術", desc: "ただのプラスチック製バケツやゴミ箱が、ダイソーの黒・茶色・赤の絵の具をスポンジで叩くだけでヴィンテージの錆びた鉄にしか見えなくなる魔法の塗装術です！", item_category: "paint", room_category: "living", price_original: "約4,000円〜（ヴィンテージ雑貨）", price_diy: "約330円", time_est: "約40分", hero_image: "https://img.youtube.com/vi/LPaCifg06Hw/maxresdefault.jpg", youtube_id: "LPaCifg06Hw", is_100yen_only: true, ingredients: [{ name: "アクリル絵の具（黒・茶・赤）（ダイソー）", price: "各110円" }, { name: "スポンジ", price: "110円" }, { name: "プラスチック製品", price: "110円" }], steps: [{ num: 1, title: "黒で下塗り", detail: "プラスチックの表面をヤスリで荒らした後、黒の絵の具で全体を塗りつぶします。" }, { num: 2, title: "茶色と赤をスポンジで叩く", detail: "スポンジに少量の茶色と赤を取り、錆びさせたい角や縁を中心にポンポンと叩きつけます。" }, { num: 3, title: "乾燥させてヴィンテージ雑貨の完成", detail: "乾くと完全に「古びた鉄」になります！アイアン家具との相性抜群です。" }] },
  { id: "wire-wall-green", title: "ワイヤーネットで壁面緑化！フェイクグリーンで作るおしゃれカフェ風ウォールアート", desc: "ダイソーのワイヤーネットを黒く塗り、フェイクグリーンを巻き付けるだけで、流行りのウォールグリーンがお部屋に誕生。殺風景な壁が一気に垢抜けます。", item_category: "wire", room_category: "living", price_original: "約5,000〜10,000円", price_diy: "約660円〜", time_est: "約20分", hero_image: "https://img.youtube.com/vi/FWhIkHUvksw/maxresdefault.jpg", youtube_id: "FWhIkHUvksw", is_100yen_only: true, ingredients: [{ name: "ワイヤーネット（黒）（ダイソー）", price: "110円" }, { name: "フェイクグリーン（ツタ状）×複数", price: "各110円" }, { name: "フック", price: "110円" }], steps: [{ num: 1, title: "ワイヤーネットにグリーンを巻き付ける", detail: "ネットの網目に沿ってフェイクグリーンをバランスよく絡ませていきます。" }, { num: 2, title: "壁にフックを設置する", detail: "壁にネットを引っ掛けるためのフックを取り付けます。" }, { num: 3, title: "ひっかけて完成", detail: "アートパネルのように壁に掛ければ完成。フェイクなので水やり不要でずっと綺麗です。" }] },
  { id: "combo-wood-iron-hc", title: "ホームセンターの本格木材＋100均アイアンで作るダイニングベンチ", desc: "100均の木材では強度が不安なベンチやテーブルは、天板だけホームセンターで購入するのが正解！脚や補強に100均のアイアンバーを使うことで、大幅にコストダウンしながらおしゃれな見栄えになります。", item_category: "wood", room_category: "living", price_original: "約15,000円〜", price_diy: "約4,000円", time_est: "約2時間", hero_image: "https://img.youtube.com/vi/KH6lNH9DpU8/maxresdefault.jpg", youtube_id: "KH6lNH9DpU8", is_100yen_only: false, ingredients: [{ name: "パイン集成材などの厚い天板", price: "約3,000円（ホームセンター）" }, { name: "木製脚", price: "約800円（ホームセンター）" }, { name: "アイアンバー（補強用）", price: "110円（セリア）" }], steps: [{ num: 1, title: "ホームセンターで木材をカット", detail: "直線カットはホームセンターに数百円で依頼。ヤスリがけは自分で行うと安上がりです。" }, { num: 2, title: "裏面に脚をボンド＆ネジで固定", detail: "脚を取り付けます。座った時のぐらつきを防ぐため、しっかりネジ留めします。" }, { num: 3, title: "アイアンバーで補強して完成", detail: "脚と脚の間にアイアンバーをつけ、強度アップしつつインダストリアルな見た目に仕上げます。" }] },
  { id: "combo-paint-hc-colorbox", title: "ホムセンのカラーボックスを100均塗料で高級ヴィンテージ木材風に", desc: "ホームセンターの安価な3段カラーボックス。そのままでは安っぽいですが、ダイソーのマスキングテープと塗料で「高級な古材風」にリメイク。3,000円以下でアンティーク家具が完成します！", item_category: "paint", room_category: "storage", price_original: "約12,000円〜", price_diy: "約2,500円", time_est: "約3時間（乾燥・下処理含む）", hero_image: "https://img.youtube.com/vi/LPaCifg06Hw/maxresdefault.jpg", youtube_id: "LPaCifg06Hw", is_100yen_only: false, ingredients: [{ name: "カラーボックス", price: "約1,200円（ホームセンター等）" }, { name: "幅広マスキングテープ", price: "110円（ダイソー）" }, { name: "アクリル絵の具・ニス", price: "各110円（ダイソー）" }], steps: [{ num: 1, title: "カラーボックス全面にマステを貼る", detail: "カラーボックスは塗料を弾く素材のため、全体に幅広のマスキングテープを貼って下地を作ります。" }, { num: 2, title: "絵の具で木目を描く", detail: "ブラウンと黒の絵の具を使い、刷毛で木目のような模様を大雑把に塗っていきます。" }, { num: 3, title: "ニスでコーティングして完成", detail: "完全に乾燥させたら水性ニスを上塗りしてツヤを出します。" }] },
  { id: "combo-wire-diy-pet", title: "結束バンド最強！ワイヤーネットで作るカスタマイズ自在のペットケージ", desc: "市販のペットケージは高くてサイズも固定。100均のワイヤーネットとジョイントを使えば、数千円で部屋の広さやペットの成長に合わせたオリジナルケージが作れます。", item_category: "wire", room_category: "living", price_original: "約8,000〜20,000円", price_diy: "約1,500〜3,000円", time_est: "約1時間", hero_image: "https://img.youtube.com/vi/HP2Tj8mvbcI/maxresdefault.jpg", youtube_id: "HP2Tj8mvbcI", is_100yen_only: true, ingredients: [{ name: "ワイヤーネット（大きめ）×10〜15枚", price: "各200円（ダイソー）" }, { name: "組み立て用ジョイント", price: "110円/4個（ダイソー）" }, { name: "結束バンド（大量）", price: "110円" }], steps: [{ num: 1, title: "底面と壁面をジョイントで組む", detail: "専用ジョイントを使ってワイヤーネットを立体に組み立てます。" }, { num: 2, title: "各結合部を結束バンドでガチガチに補強", detail: "ジョイントだけでは外れる危険があるため、全ての角と辺を結束バンドで何周も縛ります。" }, { num: 3, title: "天井や扉を工夫して完成", detail: "天井を付けたり、クリップで留める簡易扉を作れば完璧なケージの完成です！" }] },
  { id: "combo-hook-hc-curtain", title: "壁に穴を開けない！ホムセンの木枠＋100均突っ張り棒で即席カーテン", desc: "賃貸でカーテンレールがない場所に。ホームセンターの軽量木材で簡易枠を作り、100均の長尺突っ張り棒をセット。穴あけ一切なしで立派な間仕切りカーテンが完成します。", item_category: "hook", room_category: "bedroom", price_original: "約10,000円〜（業者手配）", price_diy: "約2,000円", time_est: "約1時間", hero_image: "https://img.youtube.com/vi/JeA6g0mqd7c/maxresdefault.jpg", youtube_id: "JeA6g0mqd7c", is_100yen_only: false, ingredients: [{ name: "ディアウォール等の突っ張り木材やSPF材", price: "約1,500円（ホームセンター）" }, { name: "伸縮式突っ張り棒", price: "220円（ダイソー）" }, { name: "カーテンクリップ・布", price: "各110円〜" }], steps: [{ num: 1, title: "両サイドに柱を立てる", detail: "ホームセンターの木材を使って、壁の両脇に柱となる木を突っ張らせます。" }, { num: 2, title: "柱の間に突っ張り棒を渡す", detail: "強固な木の柱の間にダイソーの突っ張り棒を設置します。直接壁に当てるより圧倒的に頑丈です。" }, { num: 3, title: "カーテンを吊るして完成", detail: "布をクリップで挟み、突っ張り棒に通せば間仕切りカーテンの完成です。" }] },
  { id: "board-peg-desk", title: "ダイソー有孔ボードで作る「浮かせる」デスクオーガナイザー", desc: "デスクの上が片付かない人必見！ダイソーのデザインボード（有孔ボード）とスタンドを組み合わせるだけで、ペンやハサミ、ケーブルなどの細々したものを空中に収納できる神アイテムが完成します。", item_category: "wood", room_category: "desk", price_original: "約3,000円〜（専用オーガナイザー）", price_diy: "約440〜660円", time_est: "約10分", hero_image: "https://img.youtube.com/vi/EDZN0EpmouM/maxresdefault.jpg", youtube_id: "EDZN0EpmouM", is_100yen_only: true, ingredients: [{ name: "デザインボード（ダイソー）", price: "110〜220円" }, { name: "専用木製スタンドセット", price: "110円" }, { name: "U字フック・ミニ棚などの専用パーツ", price: "各110円" }], steps: [{ num: 1, title: "ボードをスタンドに立てる", detail: "専用スタンドの溝にボードを差し込んで固定します。自立するので壁側の設置が不要です。" }, { num: 2, title: "専用フックを好きな位置に付ける", detail: "フックやミニ棚を穴に引っかけていきます。配置は後で変えられるので直感でOK。" }, { num: 3, title: "文房具などを収納して完成", detail: "使いたいものが一目で見渡せる最強のデスクオーガナイザーです。" }] },
  { id: "board-peg-hc-wall", title: "賃貸OK！ホムセンの有孔ボード×100均フックで巨大壁面収納", desc: "壁一面を収納にしたいなら、ホームセンターで特大の有孔ボードを買い、収納フックは100均で揃えるのがカシコイやり方。圧倒的な収納力と見栄えの良さを両立できます。", item_category: "wood", room_category: "living", price_original: "約20,000円〜", price_diy: "約5,000円", time_est: "約1時間", hero_image: "https://img.youtube.com/vi/1JyjKLCAIBs/maxresdefault.jpg", youtube_id: "1JyjKLCAIBs", is_100yen_only: false, ingredients: [{ name: "有孔ボード 特大（ホームセンター）", price: "約3,000円" }, { name: "パンチングボード掛け具（ピン式）", price: "約800円（ホームセンター等）" }, { name: "有孔ボード用フック・棚受け×大量", price: "各110円（ダイソー・セリア）" }], steps: [{ num: 1, title: "壁に掛け具を取り付ける", detail: "賃貸でも壁の跡が目立たない専用の石膏ボード用ピンで掛け具を固定します。" }, { num: 2, title: "巨大な有孔ボードを設置", detail: "ボードを取り付けます。壁との間に少し隙間がないとフックが引っかけられないため、専用具が必須です。" }, { num: 3, title: "100均パーツで無限にカスタム", detail: "カバン、帽子、鍵、工具などあらゆるものを「見せる収納」にできます。" }] },
  { id: "box-file-pantry", title: "ファイルボックスを倒すだけ！ごちゃつくパントリーが劇的に美しくなる裏ワザ", desc: "ファイルボックスは立てて使うもの、という常識を覆す収納ハック。ダイソーのファイルボックスを横に倒して重ねることで、パントリーのストック食材が取り出しやすい「棚」に早変わりします。", item_category: "wire", room_category: "kitchen", price_original: "約5,000円〜（システム収納棚）", price_diy: "約550〜1,000円", time_est: "約10分", hero_image: "https://img.youtube.com/vi/PKlRAmkKeR8/maxresdefault.jpg", youtube_id: "PKlRAmkKeR8", is_100yen_only: true, ingredients: [{ name: "A4ファイルボックス（ダイソー等）×複数", price: "各110円" }, { name: "両面テープ", price: "110円" }], steps: [{ num: 1, title: "ファイルボックスを横に倒す", detail: "背表紙側が底になるように倒します。開口部が手前に来ることで取り出しやすくなります。" }, { num: 2, title: "重ねてテープで固定する", detail: "積み重ねて両面テープで固定し、簡易的な小分け棚の形にします。" }, { num: 3, title: "レトルト食品や缶詰を収納", detail: "サイズ感が食材のストック収納にぴったり！奥のものまで見渡しやすくなります。" }] },
  { id: "box-hc-wood-cart", title: "ホムセンの木箱＋100均キャスターで作るヴィンテージ風おもちゃ箱", desc: "子供のおもちゃ箱やストック収納に。ホームセンターで売られているおしゃれなリンゴ箱風の木箱に、100均のキャスターを取り付けるだけ。重いものを入れてもスイスイ動く最高の収納になります。", item_category: "caster", room_category: "storage", price_original: "約6,000円〜", price_diy: "約2,110円", time_est: "約15分", hero_image: "https://img.youtube.com/vi/5twdTmtoqPQ/maxresdefault.jpg", youtube_id: "5twdTmtoqPQ", is_100yen_only: false, ingredients: [{ name: "木製コンテナ・木箱（ホームセンター）", price: "約2,000円" }, { name: "キャスター（ネジ止め式）×4", price: "110円（ダイソー）" }, { name: "短いネジ", price: "自宅の物でOK" }], steps: [{ num: 1, title: "コンテナを裏返す", detail: "丈夫な木箱の裏側の四隅を確認します。" }, { num: 2, title: "キャスターをネジで固定", detail: "四隅にキャスターをネジ留めします。木が分厚いのでしっかりネジが効きます。" }, { num: 3, title: "完成！", detail: "雑誌、おもちゃ、備蓄水などをポイポイ投げ込めるおしゃれな移動ワゴンの完成です。" }] },
  { id: "wood-sunoko-hc-paint", title: "100均すのこの弱点を克服！ホムセン木材と組み合わせる頑丈シェルフ", desc: "100均のすのこだけだと重い本や家電を乗せると歪んでしまう…。側板のみ頑丈なホームセンターのSPF材にし、棚板に100均すのこを使うことで強度と安さを両立させたハイブリッド棚です。", item_category: "wood", room_category: "storage", price_original: "約8,000円〜", price_diy: "約1,800円", time_est: "約1時間", hero_image: "https://img.youtube.com/vi/GPMLvYgAWvw/maxresdefault.jpg", youtube_id: "GPMLvYgAWvw", is_100yen_only: false, ingredients: [{ name: "SPF材 1x4 1820mm ×2本（ホームセンター）", price: "約800円" }, { name: "桐すのこ（幅広）×3枚", price: "各220円〜（ダイソー）" }, { name: "木ネジ", price: "110円（ダイソー）" }], steps: [{ num: 1, title: "SPF材を柱としてカットする", detail: "希望の高さにホームセンターでカットしてもらいます。" }, { num: 2, title: "すのこをSPF材にネジ打ち", detail: "頑丈なSPF材を両サイドの柱として、間にすのこを挟み込むようにネジで強固に固定します。" }, { num: 3, title: "重いものも置ける棚の完成", detail: "全て100均で作るよりも圧倒的に頑丈で、レンジや重い本なども収納できる実用的シェルフです。" }] },
  { id: "sheet-remake-kitchen", title: "賃貸キッチンの扉が見違える！ダイソーのリメイクシートで原状回復OKなDIY", desc: "茶色くて古いキッチンの扉も、ダイソーのリメイクシート（2〜3本）を貼るだけで今風のカフェスタイルに。ドライヤーを使いながら貼るとシワになりにくく、賃貸でも剥がせる貼り方のコツを解説します。", item_category: "wood", room_category: "kitchen", price_original: "約5,000〜15,000円（業者に依頼すると数万円）", price_diy: "約330〜550円", time_est: "約1.5時間", hero_image: "https://img.youtube.com/vi/0sOJVKai7RA/maxresdefault.jpg", youtube_id: "0sOJVKai7RA", is_100yen_only: true, ingredients: [{ name: "リメイクシート（ダイソー等）×複数本", price: "各110円" }, { name: "マスキングテープ（養生用）", price: "110円" }, { name: "スキージー（ヘラ）", price: "110円" }], steps: [{ num: 1, title: "扉の取っ手を外し、汚れを落とす", detail: "油汚れがあるとシートが剥がれやすくなります。中性洗剤で拭いたら、原状回復しやすいよう先にマスキングテープを下地として貼ります。" }, { num: 2, title: "シートを少しずつ貼り、スキージーで空気抜き", detail: "空気が入らないよう、スキージー（ヘラ）で押し出しながら少しずつ裏紙を剥がします。" }, { num: 3, title: "ドライヤーで角を密着させる", detail: "角やカーブ部分はドライヤーの熱を当てるとシートが伸びてピッタリ密着します。取っ手を戻して完成！" }] },
  { id: "sheet-remake-table", title: "傷だらけのテーブルが復活！大理石風リメイクシートで高級家具へ", desc: "傷だらけになった安いテーブルやこたつ天板は捨てる前にリメイク！セリアの大理石柄リメイクシートを貼るだけで、ホテルのような高級テーブルに生まれ変わります。", item_category: "wood", room_category: "living", price_original: "約10,000〜20,000円（新しいテーブルの購入）", price_diy: "約220〜550円", time_est: "約45分", hero_image: "https://img.youtube.com/vi/KH6lNH9DpU8/maxresdefault.jpg", youtube_id: "KH6lNH9DpU8", is_100yen_only: true, ingredients: [{ name: "リメイクシート（大理石柄など）", price: "各110円（セリア）" }, { name: "スキージー・カッター", price: "110円" }], steps: [{ num: 1, title: "テーブルの表面をアルコールで拭く", detail: "ホコリや油分を完全に除去します。" }, { num: 2, title: "中心から外へ向かってゆっくり貼る", detail: "大柄なデザインの場合は、柄合わせに注意しながら数枚を重ねて貼ります。スキージーでしっかり空気を抜きます。" }, { num: 3, title: "裏面に巻き込んでカット", detail: "端は数センチ余裕を持って裏側に折り込み、見えない部分でカッターで処理すると綺麗に仕上がります。" }] },
  { id: "pladan-blind-window", title: "寒さ対策に抜群！プラダンで作る簡易「二重窓」が凄すぎる", desc: "冬の窓からの冷気や、夏の熱気をシャットアウト！ダイソーのプラスチックダンボール（プラダン）とレールを組み合わせれば、断熱効果バツグンの二重窓が100均素材だけで作れます。", item_category: "wood", room_category: "bedroom", price_original: "約30,000円〜（内窓リフォーム）", price_diy: "約550〜1,000円", time_est: "約1時間", hero_image: "https://img.youtube.com/vi/JeA6g0mqd7c/maxresdefault.jpg", youtube_id: "JeA6g0mqd7c", is_100yen_only: true, ingredients: [{ name: "プラダン（大きめサイズ）×複数", price: "各110円（ダイソー）" }, { name: "ガラス戸レール（上下）", price: "各110円" }, { name: "両面テープ", price: "110円" }], steps: [{ num: 1, title: "窓枠にレールを貼る", detail: "窓枠の上下に、プラダンがスライドする用のレールを両面テープで固定します。" }, { num: 2, title: "プラダンを窓サイズにカット", detail: "カッターで簡単に切れるプラダンを、窓枠の高さに合わせて2枚カットします。中心で少し重なるサイズにします。" }, { num: 3, title: "レールにはめ込んで完成", detail: "カットしたプラダンをレールにはめ込めば完成。開け閉めも自由な簡易エコ内窓になります。" }] },
  { id: "pladan-storage-box", title: "好きなサイズの収納箱が作れる！プラダンで作るオーダーメイド収納", desc: "棚の隙間に合う収納ケースが見つからない！そんな時はプラダン（プラスチックダンボール）を折り曲げて自作しましょう。カッターで半切れ目を入れるだけで簡単に箱型になり、マスキングテープで装飾すれば既製品に見えます。", item_category: "wood", room_category: "storage", price_original: "約1,000円〜（無印良品等のケース）", price_diy: "約110〜220円", time_est: "約20分", hero_image: "https://img.youtube.com/vi/KH6lNH9DpU8/maxresdefault.jpg", youtube_id: "KH6lNH9DpU8", is_100yen_only: true, ingredients: [{ name: "プラダン", price: "110円（ダイソー等）" }, { name: "強力両面テープ", price: "110円" }, { name: "マスキングテープまたはリメイクシート", price: "110円" }], steps: [{ num: 1, title: "欲しいサイズに展開図を書く", detail: "棚の奥行きや幅に合わせて、プラダンに箱の展開図を描きます。" }, { num: 2, title: "折る部分にカッターで「半切れ目」を入れる", detail: "表面だけを薄くカッターで切ると、綺麗に90度に折り曲げることができます。" }, { num: 3, title: "立体にしてテープで留める", detail: "箱の形に組み立て、角を強力両面テープかデザイン系のマスキングテープで固定すれば完成！" }] },
  { id: "sheet-remake-door", title: "ドアの色を変えて部屋の印象を劇的チェンジ！木目調リメイクシート", desc: "建具（ドア）の色を変えるだけで、部屋全体の雰囲気がガラッと変わるのを知っていますか？ダイソーの木目調リメイクシートを室内ドアに貼るだけの、満足度が異常に高い大がかり風DIYです。", item_category: "wood", room_category: "living", price_original: "約30,000円〜（ドア交換リフォーム）", price_diy: "約440〜770円", time_est: "約2時間", hero_image: "https://img.youtube.com/vi/0sOJVKai7RA/maxresdefault.jpg", youtube_id: "0sOJVKai7RA", is_100yen_only: true, ingredients: [{ name: "木目調リメイクシート×4〜6本", price: "各110円（ダイソー・セリア）" }, { name: "スキージー", price: "110円" }], steps: [{ num: 1, title: "ドアノブを外して下地を綺麗にする", detail: "可能であればドライバーでドアノブを外し、全体を水拭き＆アルコール拭きで脱脂します。" }, { num: 2, title: "上から順に空気を抜きながら貼る", detail: "少しずつ台紙を剥がしながら、タオルやスキージーを使ってシワができないように貼り進めます。" }, { num: 3, title: "端をカットしてドアノブを戻す", detail: "はみ出た部分をカッターで綺麗に切り落とし、ドアノブ部分をくり抜いて元通りに戻せば完成です。" }] },
  { id: "pladan-cable-box", title: "プラダン＋リメイクシートで自作する高見えルーター＆ケーブルボックス", desc: "テレビ裏やデスク下のゴチャゴチャしたケーブルやWi-Fiルーター。市販の専用ボックスは意外と高いですが、プラダンで箱を作り、余ったリメイクシートを貼るだけで熱がこもらない専用ボックスが完成します。", item_category: "wood", room_category: "living", price_original: "約3,000〜5,000円", price_diy: "約220円", time_est: "約30分", hero_image: "https://img.youtube.com/vi/FWhIkHUvksw/maxresdefault.jpg", youtube_id: "FWhIkHUvksw", is_100yen_only: true, ingredients: [{ name: "プラダン", price: "110円" }, { name: "余っているリメイクシート", price: "0円（自宅の残り）" }, { name: "両面テープ", price: "110円" }], steps: [{ num: 1, title: "ルーターが収まるサイズにプラダンを切る", detail: "排熱のための空間を少し開けて、箱型になるようにプラダンをカットします。" }, { num: 2, title: "ケーブルを通す穴を開ける", detail: "側面や底面に、ケーブルが通る広めのU字型の切り込みをカッターで入れます。" }, { num: 3, title: "リメイクシートを貼って組み立てる", detail: "木目調などのシートを前面に貼り、テープで箱型に固定。上から被せるように置けばケーブルが隠れます。" }] },
  { id: "tape-mte-mold", title: "掃除の手間がゼロに！ダイソーの防カビマスキングテープ活用術", desc: "お風呂や洗面所、キッチンのコーキング（ゴムパッキン）部分に汚れやカビが生える前に！ダイソーの「カビ汚れ防止マスキングテープ」を貼っておくだけで、汚れたら剥がしてポイするだけの最強ラク家事術です。", item_category: "paint", room_category: "washroom", price_original: "約5,000円〜（特殊コーティング・洗剤）", price_diy: "約110円", time_est: "約10分", hero_image: "https://img.youtube.com/vi/1JyjKLCAIBs/maxresdefault.jpg", youtube_id: "1JyjKLCAIBs", is_100yen_only: true, ingredients: [{ name: "カビ汚れ防止マスキングテープ", price: "110円（ダイソー等）" }, { name: "拭き取り用アルコール", price: "自宅の物でOK" }], steps: [{ num: 1, title: "水回りのゴミと水分をしっかり取る", detail: "テープを貼る前に、掃除をして完全に乾燥させておかないとテープが剥がれやすくなります。" }, { num: 2, title: "端からまっすぐテープを貼る", detail: "コーキング部分を覆うように、ピンと張りながら丁寧に貼り付けます。角はしっかり押し込みます。" }, { num: 3, title: "2〜3ヶ月で貼り替える", detail: "汚れがたまってきたら剥がして捨てるだけ。掃除の手間が信じられないほど減ります！" }] },
  { id: "tape-wall-art", title: "マスキングテープで壁にアートを！賃貸OKの幾何学模様ウォールデコ", desc: "真っ白な壁が寂しいけれど、絵を飾るのはハードルが高い。そこで、100均の黒やゴールドのマスキングテープを使い、壁に直接「図形」を描くウォールデコが海外で大流行。剥がせるので賃貸でも安心です。", item_category: "paint", room_category: "living", price_original: "約3,000〜10,000円（ウォールステッカーやポスター）", price_diy: "約220円", time_est: "約30分", hero_image: "https://img.youtube.com/vi/EDZN0EpmouM/maxresdefault.jpg", youtube_id: "EDZN0EpmouM", is_100yen_only: true, ingredients: [{ name: "マスキングテープ（太め・黒や金など）", price: "110〜220円（ダイソー・セリア）" }], steps: [{ num: 1, title: "壁のホコリを落とし、デザインを決める", detail: "山脈のようなジグザグや、家型などの簡単な幾何学模様をイメージします。" }, { num: 2, title: "テープをまっすぐ貼っていく", detail: "テープを軽く引っ張りながら壁に貼り、絵を描くように線を引いていきます。" }, { num: 3, title: "模様の完成", detail: "飽きたらすぐに剥がして違うデザインを楽しめる、手軽なアート壁の完成です！" }] },
  { id: "hook-tsuppari-shoes", title: "靴箱の収納力が2倍に！突っ張り棒1本でできるヒール収納術", desc: "靴箱にヒールが高くて無駄な隙間ができていませんか？手前に突っ張り棒を1本渡し、ヒール部分を引っ掛けるようにして靴を収納するだけで、上部のデッドスペースが使えるようになり収納力が一気に2倍になります。", item_category: "hook", room_category: "entrance", price_original: "約2,000〜4,000円（市販のシューズホルダー）", price_diy: "約110円", time_est: "約5分", hero_image: "https://img.youtube.com/vi/JeA6g0mqd7c/maxresdefault.jpg", youtube_id: "JeA6g0mqd7c", is_100yen_only: true, ingredients: [{ name: "伸縮式突っ張り棒", price: "110円（ダイソー等）" }], steps: [{ num: 1, title: "靴箱の上部手前に突っ張り棒を設置", detail: "靴を入れた状態で、ヒール部分が引っかかる位置を計算して突っ張り棒を固定します。" }, { num: 2, title: "靴を上下に重ねて収納する", detail: "下段に通常通り靴を置き、上段（突っ張り棒）に別のヒール靴を引っ掛けます。" }, { num: 3, title: "完成！", detail: "シューズホルダーを買うよりも安く、かつスマートに収納できます。スニーカーなどの場合は2本使って棚にするのもアリです。" }] },
  { id: "combo-hook-hc-noren", title: "ホムセンの布と100均突っ張り棒で作る、のれん風目隠しカーテン", desc: "玄関やキッチンの入り口のちょっとした目隠しに。100均ののれんではサイズや質感に限界があるため、ホームセンターの好きな布（切り売り）と100均の突っ張り棒＆リングクリップを利用して、自分の部屋にぴったりのパーテーションを作ります。", item_category: "hook", room_category: "kitchen", price_original: "約4,000円〜（オーダーのれん）", price_diy: "約1,200円", time_est: "約15分", hero_image: "https://img.youtube.com/vi/To61TytErh8/maxresdefault.jpg", youtube_id: "To61TytErh8", is_100yen_only: false, ingredients: [{ name: "好きな布（切り売り）", price: "約1,000円（ホームセンター等）" }, { name: "突っ張り棒", price: "110円（ダイソー）" }, { name: "カーテンリングクリップ", price: "110円（ダイソー）" }], steps: [{ num: 1, title: "端がほつれない布を選ぶか、端処理をする", detail: "ホムセンで布を買う場合、切ったまま使える素材（または裾上げテープを使用）が便利です。" }, { num: 2, title: "布にクリップをつける", detail: "上端に10cm等間隔でカーテンリングクリップを挟んでいきます。" }, { num: 3, title: "突っ張り棒に通して設置", detail: "リングを突っ張り棒に通し、入り口にピタッと設置すれば素敵な目隠し空間が完成します。" }] },
  { id: "hook-tsuppari-trash", title: "ゴミ袋の交換が一瞬で終わる！ゴミ箱内の突っ張り棒収納術", desc: "ゴミの日に新しい袋を探すのが面倒…。そんなイライラを解消するテクニック！ゴミ箱の奥（内側）に短い突っ張り棒を設置し、そこに予備のゴミ袋をかけておけば、ゴミ袋のセットから回収までが同じ場所で3秒で終わります。", item_category: "hook", room_category: "kitchen", price_original: "約1,500〜3,000円（専用ストッカー付きゴミ箱）", price_diy: "約110円", time_est: "約3分", hero_image: "https://img.youtube.com/vi/TQvrDVQsd8E/maxresdefault.jpg", youtube_id: "TQvrDVQsd8E", is_100yen_only: true, ingredients: [{ name: "短い突っ張り棒", price: "110円（ダイソー）" }], steps: [{ num: 1, title: "ゴミ箱の内側に突っ張り棒をセット", detail: "ゴミ箱の中央・奥側に、短い突っ張り棒を横にぴったり張ります。" }, { num: 2, title: "予備のゴミ袋を引っ掛ける", detail: "指定ゴミ袋などの予備を突っ張り棒に引っ掛けておきます。" }, { num: 3, title: "次の回からすぐセット可能に", detail: "ゴミを捨てた後、底からスッと引き抜きそのままセットするだけ。最高の家事効率化ハックです！" }] },
  { id: "iron-bar-towel", title: "定番中の定番！セリアのアイアンバーで作る高見えタオルハンガー", desc: "100均アイアンバーの使い方として最も王道かつ実用的なのがタオルハンガー。洗面所やキッチンの壁にネジ留めするだけで、備え付けのようなアイアン製タオル掛けがたった110円で完成します。", item_category: "iron", room_category: "washroom", price_original: "約1,500〜3,000円（市販のアイアンタオル掛け）", price_diy: "約110円", time_est: "約10分", hero_image: "https://img.youtube.com/vi/1JyjKLCAIBs/maxresdefault.jpg", youtube_id: "1JyjKLCAIBs", is_100yen_only: true, ingredients: [{ name: "インテリアアイアンウォールバー", price: "110円（セリア）" }, { name: "短いネジ×4本", price: "110円（ダイソー等）" }], steps: [{ num: 1, title: "設置位置を決めて水平を測る", detail: "斜めになると目立つため、スマホの水平器アプリなどを使ってまっすぐな位置を決めます。" }, { num: 2, title: "左右の穴にネジを打つ", detail: "賃貸の場合はネジの代わりに石膏ボード用の専用ピン（穴が目立たないもの）を使用します。" }, { num: 3, title: "タオルを掛けて完成", detail: "シンプルなデザインがどんなインテリアにも馴染みます。" }] },
  { id: "iron-bar-slippers", title: "玄関がスッキリ！アイアンバー2本で作るスリッパラック", desc: "玄関にスリッパが散乱していませんか？壁や靴箱の側面にアイアンバーを2本上下に並べて固定するだけで、スリッパを挟んで収納できるスマートな壁掛けラックができます。", item_category: "iron", room_category: "entrance", price_original: "約3,000円〜（スリッパスタンド）", price_diy: "約220円", time_est: "約15分", hero_image: "https://img.youtube.com/vi/D6fknJQ5VrU/maxresdefault.jpg", youtube_id: "D6fknJQ5VrU", is_100yen_only: true, ingredients: [{ name: "アイアンウォールバー×2", price: "各110円（セリア）" }], steps: [{ num: 1, title: "スリッパの長さを測る", detail: "スリッパの甲の部分が引っかかり、かつ落ちない絶妙な幅（上下の間隔）にアタリをつけます。" }, { num: 2, title: "アイアンバーを上下2段に固定", detail: "靴箱の側面などの木材部分であれば、プラスドライバー1本で簡単にネジ打ちできます。" }, { num: 3, title: "スリッパを挟んで収納", detail: "上のバーと下のバーの間にスリッパを差し込んで完成。直置きしないため床掃除も簡単です。" }] },
  { id: "iron-bar-shelf-guard", title: "アイアンバーで落下防止！ディスプレイ棚のアップグレード術", desc: "せっかく取り付けたウォールシェルフから物が落ちてしまう…。棚板の前面にセリアのアイアンバーをひっくり返して取り付けるだけで、落下防止の柵（ガード）になり、さらにカフェ風のおしゃれ度もUPします。", item_category: "iron", room_category: "living", price_original: "約4,000円〜（アイアンガード付きシェルフ）", price_diy: "約330〜550円", time_est: "約20分", hero_image: "https://img.youtube.com/vi/BVb3GgUuT0Q/maxresdefault.jpg", youtube_id: "BVb3GgUuT0Q", is_100yen_only: true, ingredients: [{ name: "板板・すのこ（棚板用）", price: "110〜220円（ダイソー・セリア）" }, { name: "アイアンウォールバー", price: "110円（セリア）" }, { name: "アイアンブラケット（棚受け用）×2", price: "220円（セリア）" }], steps: [{ num: 1, title: "棚板に棚受け（ブラケット）を固定", detail: "通常のウォールシェルフを作る手順で棚板の下にブラケットを取り付けます。" }, { num: 2, title: "棚板の上面手前にアイアンバーを固定", detail: "コの字型になっているアイアンバーを立たせるようにして、棚板の上面の手前側にネジ留めします。" }, { num: 3, title: "壁に設置して完成", detail: "小瓶や本を並べても落ちてこない、見た目も実用性も兼ね備えた棚の完成です。" }] },
  { id: "box-pull-out-sink", title: "シンク下が劇的改善！100均ファイルボックス×キャスターで引き出し収納", desc: "奥行きがあって奥のものが取り出しにくいキッチンシンク下。ダイソーのスリムファイルボックスの裏にミニキャスターを貼るだけで、奥の調味料や鍋フタが片手で引き出せるようになります。", item_category: "caster", room_category: "kitchen", price_original: "約3,000〜5,000円（スライド式シンク下収納）", price_diy: "約220円", time_est: "約5分", hero_image: "https://img.youtube.com/vi/PKlRAmkKeR8/maxresdefault.jpg", youtube_id: "PKlRAmkKeR8", is_100yen_only: true, ingredients: [{ name: "A4ファイルボックス（ワイドまたはスリム）", price: "110円（ダイソー）" }, { name: "ピタッとキャスター 4個入", price: "110円（ダイソー）" }], steps: [{ num: 1, title: "ファイルボックスの裏を拭く", detail: "粘着テープがしっかりつくよう、裏面のホコリを拭き取ります。" }, { num: 2, title: "キャスターを前後に貼る", detail: "前後にまっすぐ引き出せるよう、キャスターの向きを奥行き方向に揃えて4箇所に貼り付けます。" }, { num: 3, title: "調味料ボトル等を入れて収納", detail: "油やしょうゆの重いボトルを入れても、キャスターのおかげで指一本でするする引き出せます！" }] },
  { id: "combo-box-hc-board", title: "ホムセンの野地板＋100均スクエアボックスで作る北欧風おもちゃラック", desc: "ダイソーで大人気のフタ付き「スクエア収納ボックス」。これらがぴったり収まる木製ラックをホームセンターの安い「野地板（のじいた）」で自作すれば、数万円するような北欧風の子供部屋おもちゃラックが激安で完成します！", item_category: "wood", room_category: "bedroom", price_original: "約10,000〜25,000円（木製おもちゃラック）", price_diy: "約2,500〜3,500円", time_est: "約2.5時間", hero_image: "https://img.youtube.com/vi/5twdTmtoqPQ/maxresdefault.jpg", youtube_id: "5twdTmtoqPQ", is_100yen_only: false, ingredients: [{ name: "ダイソー スクエア収納ボックス（大）×6個", price: "約1,320円" }, { name: "野地板（ホムセンのもっとも安い木材）", price: "約1,000円" }, { name: "木ネジ等", price: "約200円" }], steps: [{ num: 1, title: "野地板をやすりがけする", detail: "野地板はザラザラなので、電動サンダーや紙やすりで表面を滑らかにします。" }, { num: 2, title: "ボックスのサイズに合わせて枠を組む", detail: "ボックスが3段×2列で入るように寸法を測り、ハシゴ状の枠を作ってネジで固定します。" }, { num: 3, title: "ボックスをセットして完成", detail: "木枠にダイソーのボックスをスライドして入れれば、大容量でおしゃれなおもちゃラックの完成です！" }] },
  { id: "magnet-hook-coat", title: "玄関のコート掛けが一瞬で完成！強力マグネットフック活用術", desc: "帰宅したらすぐコートを掛けられる場所が欲しい！ダイソーの強力マグネットフックを玄関ドアや下駄箱の側面に取り付けるだけで、工事不要のコート掛けが完成。バッグや帽子にも対応できます。", item_category: "magnet", room_category: "entrance", price_original: "約2,000〜4,000円（壁掛けコート掛け）", price_diy: "約110〜330円", time_est: "約3分", hero_image: "https://img.youtube.com/vi/PYKKPf-ayvg/maxresdefault.jpg", youtube_id: "PYKKPf-ayvg", is_100yen_only: true, ingredients: [{ name: "強力マグネットフック（ダイソー）", price: "110〜220円" }], steps: [{ num: 1, title: "玄関ドアや下駄箱にくっつける", detail: "マグネットが引き付く金属面（スチール製のドア・下駄箱の側面など）にくっつけるだけです。" }, { num: 2, title: "コート・バッグを掛ける", detail: "帰宅後すぐに引っ掛けることができ、玄関がスッキリします。" }, { num: 3, title: "用途に合わせて位置を変える", detail: "取り外しが自由なので季節や家族構成に合わせて場所を変えられます。" }] },
  { id: "magnet-spice-organizer", title: "見せるスパイス収納に！マグネット缶で冷蔵庫に貼り付けるスパイスラック", desc: "乱雑になりがちなスパイスは「浮かせる」が正解！セリアのマグネット付きスパイスボトルやマグネット缶にスパイスを移して冷蔵庫側面に貼り付けると、カフェのような高見えスパイスラックが完成します。", item_category: "magnet", room_category: "kitchen", price_original: "約5,000〜8,000円（専用スパイスラック）", price_diy: "約660〜1,100円", time_est: "約20分", hero_image: "https://img.youtube.com/vi/UtVLfQX8miY/maxresdefault.jpg", youtube_id: "UtVLfQX8miY", is_100yen_only: true, ingredients: [{ name: "マグネットスパイスボトル or 丸型マグネット缶", price: "各110円（セリア）" }, { name: "ラベルシール（中身の種類を書く用）", price: "110円" }], steps: [{ num: 1, title: "スパイスをボトル・缶に移す", detail: "よく使うスパイス（塩・砂糖・コショウ・唐辛子など）を移しましょう。" }, { num: 2, title: "ラベルを書いて貼る", detail: "中身が分かるように蓋や側面にラベルシールを貼ります。" }, { num: 3, title: "冷蔵庫や換気扇フードに貼り付けて完成", detail: "並べて貼るだけで料理雑誌のような景色になります！使いたいものをすぐ取れるので調理効率もUP。" }] },
  { id: "wire-desk-monitor-arm", title: "ワイヤーネットでモニター下の配線をスッキリ！ケーブルトレー自作DIY", desc: "デスクのモニター下に垂れ下がるケーブルをどうにかしたい…。ダイソーのワイヤーネットをデスク裏面に両面テープで貼り付けるだけで、ケーブルをまとめて隠せる「浮かせるケーブルトレー」が完成します！", item_category: "wire", room_category: "desk", price_original: "約2,000〜5,000円（ケーブルトレー）", price_diy: "約330円", time_est: "約10分", hero_image: "https://img.youtube.com/vi/EDZN0EpmouM/maxresdefault.jpg", youtube_id: "EDZN0EpmouM", is_100yen_only: true, ingredients: [{ name: "ワイヤーネット（小〜中）", price: "200円（ダイソー）" }, { name: "強力両面テープ", price: "110円" }, { name: "結束バンド（ケーブル固定用）", price: "110円" }], steps: [{ num: 1, title: "デスク裏面にネットを当てる", detail: "デスク天板の裏側、目線からケーブルが隠れる位置にワイヤーネットを当てて位置決めします。" }, { num: 2, title: "強力両面テープで固定", detail: "ネットのフレームに両面テープを貼り、デスクの裏にしっかり圧着します。" }, { num: 3, title: "ケーブルをまとめて引っ掛ける", detail: "延長コードやルーターをネットの上に置き、結束バンドで軽く固定します。床からケーブルが消えてスッキリ！" }] },
  { id: "wood-photo-stand", title: "ダイソー材で量産可能！100円で作るミニウッドフォトスタンド", desc: "ポストカードや写真を飾るフォトスタンドは1個300〜500円しますが、ダイソーの細い木材を4本組み合わせるだけで1個100円で何個でも作れます。塗装でオリジナル感が出せて、プレゼントにも最高です。", item_category: "wood", room_category: "desk", price_original: "約500〜1,500円（市販フォトフレーム）", price_diy: "約110〜220円/個", time_est: "約20分", hero_image: "https://img.youtube.com/vi/HKweETmKsCQ/maxresdefault.jpg", youtube_id: "HKweETmKsCQ", is_100yen_only: true, ingredients: [{ name: "角材・丸棒（細め、ダイソー）", price: "各110円" }, { name: "木工ボンド", price: "110円" }, { name: "お好みの塗料", price: "110円（ダイソー）" }], steps: [{ num: 1, title: "木材を好みの長さにカット", detail: "ハサミや100均のミニのこぎりで、フォトスタンドの縦横のサイズにカットします。" }, { num: 2, title: "木工ボンドで額縁の形に組む", detail: "写真や絵ハガキのサイズに合わせて、4本の木材を口の字形に組んでボンドで接着します。" }, { num: 3, title: "塗装して写真をはさんで完成", detail: "乾いたら好みの色に塗装。クリップで写真を挟む形にするのが最も簡単で、入れ替えも自由です。" }] },
  { id: "combo-iron-caster-wagon", title: "アイアンバー＋キャスターで作るインダストリアル風キッチンワゴン", desc: "流行りのアイアン×木のキッチンワゴンはインスタで何万いいねも稼ぐ人気DIY。セリアのアイアンバーとダイソーのすのこ＋キャスターを組み合わせれば、買うと2万円以上するような高見えワゴンが2,000円台で完成します！", item_category: "iron", room_category: "kitchen", price_original: "約15,000〜25,000円", price_diy: "約1,800〜2,500円", time_est: "約2時間", hero_image: "https://img.youtube.com/vi/BVb3GgUuT0Q/maxresdefault.jpg", youtube_id: "BVb3GgUuT0Q", is_100yen_only: true, ingredients: [{ name: "アイアンウォールバー×6本（セリア）", price: "660円" }, { name: "桐すのこ 大×3枚（ダイソー）", price: "600〜900円" }, { name: "キャスター×4（ダイソー）", price: "110円" }, { name: "木工ボンド＋ネジ", price: "220円" }], steps: [{ num: 1, title: "アイアンバーでフレームを組む", detail: "アイアンバーを縦・横・斜めに組み合わせてワゴンの骨格となるフレームを作ります。連結はネジ留めするか結束バンドで固定します。" }, { num: 2, title: "すのこを棚板として固定する", detail: "フレームの各段にすのこを棚板として渡し、木工ボンド＋ネジでしっかり固定します。" }, { num: 3, title: "キャスターを底面につけて完成", detail: "4隅にキャスターをつければ、コンロ横・冷蔵庫横をスイスイ動けるインダストリアル風ワゴンの完成です！" }] },
  { id: "paint-chalk-blackboard", title: "ダイソーの黒板塗料でどこでも黒板に！家族の伝言ボードDIY", desc: "壁・板・缶・スプレー缶……塗れる面であれば何でも黒板にしてしまえる「黒板塗料」がダイソーで110円で手に入ります。カフェにあるような家族の伝言ボードやキッチンのメモスペースを超お手軽に作れます。", item_category: "paint", room_category: "kitchen", price_original: "約4,000〜8,000円（黒板壁面パネル）", price_diy: "約220〜440円", time_est: "約30分（乾燥含む）", hero_image: "https://img.youtube.com/vi/6CPo3XfMkEI/maxresdefault.jpg", youtube_id: "6CPo3XfMkEI", is_100yen_only: true, ingredients: [{ name: "黒板塗料（ブラック）（ダイソー）", price: "110円" }, { name: "刷毛 or スポンジ", price: "110円" }, { name: "板材 or 木製パネル", price: "110〜220円（ダイソー）" }], steps: [{ num: 1, title: "板を用意して塗装する", detail: "ダイソーの板材や使わなくなったすのこなどに、黒板塗料を刷毛で均一に塗ります。" }, { num: 2, title: "完全乾燥後にもう1回塗る", detail: "1回目が乾いたら2〜3回重ね塗りすることで、チョークの粉が定着しやすくなります。" }, { num: 3, title: "24時間後から使用開始", detail: "完全に乾いたら側面を枠で囲んだり、壁に掛けて完成。最初にチョーク全面を塗りつぶしてから消すと書きやすくなります。" }] },
  { id: "hook-over-door", title: "穴あけゼロ！ドアの上に掛けるだけの「オーバードアフック」活用法8選", desc: "ドアの上部に引っ掛けるだけで使えるオーバードアフック（ドアかけフック）。賃貸でも穴あけなしでコート・バッグ・掃除道具・タオルなど何でも掛けられ、玄関・洗面所・クローゼットが一気に整います。", item_category: "hook", room_category: "entrance", price_original: "各1,000〜2,000円（市販ドアフック）", price_diy: "各110円以内", time_est: "約5分", hero_image: "https://img.youtube.com/vi/CaRNHSJOfFM/maxresdefault.jpg", youtube_id: "CaRNHSJOfFM", is_100yen_only: true, ingredients: [{ name: "オーバードアフック（各種）（ダイソー or セリア）", price: "110円" }], steps: [{ num: 1, title: "ドアの厚さを確認する", detail: "ドアの厚み（2〜4cm程度が多い）に対応した商品を選びます。ダイソーには数種類あります。" }, { num: 2, title: "ドア上部に引っ掛けるだけ", detail: "フックをドア上部の端に引っ掛けます。傷防止パッドがついているものを選ぶと安心です。" }, { num: 3, title: "8つの活用法でフル活用", detail: "①コート ②バッグ ③帽子 ④洗面タオル ⑤換気扇フィルター ⑥エプロン ⑦掃除用ビニール袋 ⑧コードレス掃除機のスタンドとして。ドア1枚で8つの収納が増えます！" }] },
  { id: "combo-wire-sunoko-partition", title: "すのこ＋ワイヤーネットで作るインテリア映えの「置くだけパーテーション」", desc: "部屋を仕切りたいけどプロに頼むのは大げさ…。すのこ数枚をちょうつがいで繋いだ「屏風型パーテーション」に、セリアのワイヤーネットを埋め込むことで収納機能まで持たせた超実用的な仕切りが完成します！", item_category: "wire", room_category: "living", price_original: "約15,000〜30,000円（間仕切り家具）", price_diy: "約1,500〜2,000円", time_est: "約1.5時間", hero_image: "https://img.youtube.com/vi/GPMLvYgAWvw/maxresdefault.jpg", youtube_id: "GPMLvYgAWvw", is_100yen_only: true, ingredients: [{ name: "桐すのこ（大）×3〜4枚", price: "各220〜330円（ダイソー）" }, { name: "ちょうつがい×各2個", price: "各110円" }, { name: "ワイヤーネット×1〜2枚", price: "各200円（ダイソー）" }, { name: "結束バンド", price: "110円" }], steps: [{ num: 1, title: "すのこ2枚をちょうつがいで繋ぐ", detail: "2枚のすのこをちょうつがいで蝶番として繋ぎます。3枚以上でも同様に連結できます。" }, { num: 2, title: "すのこの隙間にワイヤーネットをはめる", detail: "すのこの板の間にワイヤーネットを差し込み、結束バンドで固定するとフック収納スペースになります。" }, { num: 3, title: "屏風状に折り曲げて自立させる", detail: "W字や外開きの形に広げれば自立します。S字フックでバッグや小物を掛ければ完成です！" }] },
  { id: "caster-freezer-drawer", title: "冷凍庫の奥が取り出せる！ワイヤーかごキャスター引き出し術", desc: "冷凍庫の奥に入れたものが賞味期限切れに…というストレスを解消！セリアのワイヤーバスケットとミニキャスターを組み合わせることで、冷凍庫内に引き出し式の収納が作れます。", item_category: "caster", room_category: "kitchen", price_original: "約3,000〜5,000円（専用収納ボックス）", price_diy: "約220〜330円", time_est: "約5分", hero_image: "https://img.youtube.com/vi/GVMbtYQpQuI/maxresdefault.jpg", youtube_id: "GVMbtYQpQuI", is_100yen_only: true, ingredients: [{ name: "ワイヤーバスケット（フラット型・低め）（セリア）", price: "110〜220円" }, { name: "ミニキャスター×4（ダイソー）", price: "110円" }, { name: "結束バンド", price: "110円" }], steps: [{ num: 1, title: "バスケット底にキャスターを付ける", detail: "バスケット底面の格子にキャスターを結束バンドで縛ります。" }, { num: 2, title: "冷凍庫に入れて食品を収納", detail: "アイス・冷凍食品・保冷剤などを収納します。" }, { num: 3, title: "指一本で引き出せて完成", detail: "重い食材ごと引き出しのように引き出せます。奥が一目瞭然になります！" }] },
  { id: "magnet-whiteboard", title: "磁石もマーカーも使える！スチールシートでDIYホワイトボード", desc: "ダイソーのスチールシートをボードに貼り付けるだけで、磁石もホワイトボードマーカーも使えるオリジナルホワイトボードが作れます。小さいサイズから大きいサイズまで自由自在！", item_category: "magnet", room_category: "desk", price_original: "約5,000〜15,000円（マグネット対応ホワイトボード）", price_diy: "約330〜660円", time_est: "約20分", hero_image: "https://img.youtube.com/vi/AejOXLlURHw/maxresdefault.jpg", youtube_id: "AejOXLlURHw", is_100yen_only: true, ingredients: [{ name: "スチールシート（ダイソー等）", price: "110〜220円" }, { name: "ホワイトボード用シート or 白リメイクシート", price: "110〜330円" }, { name: "強力両面テープ", price: "110円" }], steps: [{ num: 1, title: "スチールシートをベース板に貼る", detail: "MDF板や厚紙などの硬いベースにスチールシートを両面テープで貼ります。" }, { num: 2, title: "白いシートを上から重ねて貼る", detail: "スチールの上からホワイトボードシートを貼ることで、磁石もマーカーも両対応になります。" }, { num: 3, title: "壁に設置して完成", detail: "どこでも使えるホワイトボードが完成！スケジュール管理やメモに役立ちます。" }] },
  { id: "paint-chalk-blackboard", title: "ダイソーの黒板塗料でどこでも黒板に！カフェ風伝言ボードDIY", desc: "ダイソーの黒板塗料を塗るだけでどんな板でも黒板になります。カフェにあるような家族の伝言ボードやキッチンのメモスペースを超お手軽に作れます。", item_category: "paint", room_category: "kitchen", price_original: "約4,000〜8,000円（黒板パネル）", price_diy: "約220〜440円", time_est: "約30分（乾燥含む）", hero_image: "https://img.youtube.com/vi/6CPo3XfMkEI/maxresdefault.jpg", youtube_id: "6CPo3XfMkEI", is_100yen_only: true, ingredients: [{ name: "黒板塗料（ダイソー）", price: "110円" }, { name: "刷毛 or スポンジ", price: "110円" }, { name: "板材（ダイソー）", price: "110〜220円" }], steps: [{ num: 1, title: "板に黒板塗料を塗る", detail: "ダイソーの板材に黒板塗料を刷毛で均一に塗ります。" }, { num: 2, title: "完全乾燥後に重ね塗り", detail: "1回目が乾いたら2〜3回重ね塗りします。チョークが定着しやすくなります。" }, { num: 3, title: "24時間後から使用開始", detail: "最初にチョーク全面を塗りつぶしてから消すと書きやすくなります。壁に掛けて完成！" }] }
